import{_ as e,o,c as s,a3 as r}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Idade das partes","description":"","frontmatter":{"title":"Idade das partes","id":"eproc-idade-partes","plataforma":"eproc","grupo":"Painel do processo","plano":"free","desde":"1.10.0","padrao":"desligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-idade-partes"}]]},"headers":[],"relativePath":"funcionalidades/eproc-idade-partes.md","filePath":"funcionalidades/eproc-idade-partes.md"}'),d={name:"funcionalidades/eproc-idade-partes.md"};function t(i,a,n,l,c,p){return o(),s("div",null,a[0]||(a[0]=[r('<h1 id="idade-das-partes" tabindex="-1">Idade das partes <a class="header-anchor" href="#idade-das-partes" aria-label="Permalink to &quot;Idade das partes&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>O eproc mostra a idade ao lado do nome de autores e réus, mas não em outros polos, como Criança/Adolescente. Este recurso mostra a idade dessas pessoas logo após o nome, sem que você precise clicar em cada uma para consultar a data de nascimento.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, tela do processo, tabela &quot;Partes e Representantes&quot;: ao lado do nome de cada pessoa física que aparece sem idade.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Ligue o recurso nas configurações do eploc (ele vem desligado).</li><li>Abra um processo. Enquanto o eploc consulta a data de nascimento, um pequeno indicador de carregamento aparece ao lado do nome; em seguida ele dá lugar à idade, por exemplo &quot;(6 anos)&quot;, com o logo do eploc à frente para indicar que a informação vem do eploc.</li><li>Passe o mouse sobre a idade para ver a data de nascimento.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><ul><li><strong>Destacar quem já tem 18 anos ou mais</strong>: a idade de quem já atingiu a maioridade aparece realçada. Ligado por padrão.</li><li><strong>Avisar quando faltarem até quantos dias para os 18 anos</strong>: ao lado da idade aparece, por exemplo, &quot;faz 18 em 12 dias&quot;. O padrão é 90 dias; use 0 para desligar o aviso.</li></ul><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>A consulta é a mesma que o eproc faz quando você clica no nome da parte, feita em segundo plano, até três por vez. Em processos com muitas partes, as idades podem levar alguns segundos para aparecer todas.</li><li>As partes que o eproc já mostra com idade não são consultadas de novo.</li><li>As datas de nascimento não são guardadas pelo eploc: valem só enquanto a página do processo está aberta.</li></ul>',11)]))}const f=e(d,[["render",t]]);export{m as __pageData,f as default};
